   169→	@Override
   170→	public void processOpts() {
   171→		BiFunction<String, String, String> getOrDefault = (key,
   172→				defaultValue) -> (String) additionalProperties.computeIfAbsent(key, k -> defaultValue);
   173→
   174→		// reuse package if other packages are not provided
   175→
   176→		var packageName = getOrDefault.apply(CodegenConstants.PACKAGE_NAME, "changeMe");
   177→		apiPackage = getOrDefault.apply(CodegenConstants.API_PACKAGE, packageName);
   178→		modelPackage = getOrDefault.apply(CodegenConstants.MODEL_PACKAGE, packageName);
   179→		invokerPackage = getOrDefault.apply(CodegenConstants.INVOKER_PACKAGE, packageName);
   180→		additionalProperties.put("isModelImport", !apiPackage.equals(modelPackage));
   181→
   182→		// process flags - this class
   183→
   184→		if (additionalProperties.containsKey(USE_BEANVALIDATION)) {
   185→			useBeanValidation = convertPropertyToBooleanAndWriteBack(USE_BEANVALIDATION);
   186→		}
   187→		if (additionalProperties.containsKey(USE_GENERIC_RESPONSE)) {
   188→			useGenericResponse = convertPropertyToBooleanAndWriteBack(USE_GENERIC_RESPONSE);
   189→		}
   190→		if (additionalProperties.containsKey(USE_OPTIONAL)) {
   191→			useOptional = convertPropertyToBooleanAndWriteBack(USE_OPTIONAL);
   192→		}
   193→		if (additionalProperties.containsKey(INTROSPECTED)) {
   194→			introspected = convertPropertyToBooleanAndWriteBack(INTROSPECTED);
   195→		}
   196→		if (additionalProperties.containsKey(DATETIME_RELAXED)) {
   197→			dateTimeRelaxed = convertPropertyToBooleanAndWriteBack(DATETIME_RELAXED);
   198→		}
   199→		if (additionalProperties.containsKey(PAGEABLE)) {
   200→			pageable = convertPropertyToBooleanAndWriteBack(PAGEABLE);
   201→		}
   202→		if (additionalProperties.containsKey(SUPPORT_ASYNC)) {
   203→			supportAsync = convertPropertyToBooleanAndWriteBack(SUPPORT_ASYNC);
   204→		}
   205→		if (additionalProperties.containsKey(GENERATE_API_TESTS)) {
   206→			generateApiTests = convertPropertyToBooleanAndWriteBack(GENERATE_API_TESTS);
   207→		}
   208→		if (additionalProperties.containsKey(OPENAPI_NULLABLE)) {
   209→			openApiNullable = convertPropertyToBooleanAndWriteBack(OPENAPI_NULLABLE);
   210→		}
   211→		if (additionalProperties.containsKey(GENERATE_EXAMPLES)) {
   212→			generateExamples = convertPropertyToBooleanAndWriteBack(GENERATE_EXAMPLES);
   213→		}
   214→
   215→		// we do not generate projects, only api, set source and test folder
   216→
   217→		templateDir = "Micronaut";
   218→		projectFolder = getOrDefault.apply("projectFolder", "generated-sources");
   219→		projectTestFolder = getOrDefault.apply("projectTestFolder", "generated-test-sources");
   220→		sourceFolder = getOrDefault.apply(SOURCE_FOLDER, projectFolder + File.separator + "openapi");
   221→		testFolder = getOrDefault.apply("testFolder", projectTestFolder + File.separator + "openapi");
   222→		modelNameSuffix = getOrDefault.apply(MODEL_NAME_SUFFIX, modelNameSuffix);
   223→		isClient = additionalProperties.containsKey(CLIENT_ID);
   224→
   225→		// add files to generate
   226→
   227→		if (isClient) {
   228→			apiTemplateFiles.put("apiClient.mustache", "Client.java");
   229→		} else {
   230→			apiTemplateFiles.put("apiServer.mustache", ".java");
   231→			if (pageable) {
   232→				addSupportingFile(sourceFolder, invokerPackage, "PageableProvider");
   233→			}
   234→			if (generateApiTests && !openAPI.getPaths().isEmpty()) {
   235→				apiTestTemplateFiles.put("testSpec.mustache", "Spec.java");
   236→				apiTestTemplateFiles.put("testClient.mustache", "Client.java");
   237→				addSupportingFile(testFolder, invokerPackage, "HttpResponseAssertions");
   238→			}
   239→		}
   240→		if (generateExamples) {
   241→			modelTestTemplateFiles.put("testExampleObject.mustache", "Example.java");
   242→		}
   243→
   244→		// add type mappings for mustache
   245→
   246→		additionalProperties.put("type.Nullable", typeMapping.get("Nullable"));
   247→		additionalProperties.put("type.Nonnull", typeMapping.get("Nonnull"));
   248→		additionalProperties.put("type.Inject", typeMapping.get("Inject"));
   249→		additionalProperties.put("type.Singleton", typeMapping.get("Singleton"));
   250→		additionalProperties.put("type.MultipartBody", typeMapping.get("MultipartBody"));
   251→		Optional.ofNullable(typeMapping.get("Generated"))
   252→				.filter(type -> !type.isBlank())
   253→				.ifPresent(type -> additionalProperties.put("type.Generated", type));
   254→	}
