   256→	@Override
   257→	public CodegenOperation fromOperation(String path, String httpMethod, Operation source, List<Server> servers) {
   258→
   259→		var operation = super.fromOperation(path, httpMethod, source, servers);
   260→		var produces = operation.produces == null ? List.<Map<String, String>>of() : operation.produces;
   261→
   262→		// warn if operation has wildcard/range responses
   263→
   264→		if (operation.responses.stream().anyMatch(CodegenResponse::isWildcard)) {
   265→			throw new SpecValidationException("Wildcard responses are not supported.");
   266→		}
   267→		if (operation.responses.stream().anyMatch(CodegenResponse::isRange)) {
   268→			throw new SpecValidationException("Range responses are not supported.");
   269→		}
   270→
   271→		// get responses for considering repsonse type
   272→
   273→		var responses = operation.responses.stream().filter(r -> r.is2xx || r.is3xx).collect(Collectors.toList());
   274→		var responsesCodes = responses.stream().map(r -> Integer.parseInt(r.code)).collect(Collectors.toList());
   275→		var responseGeneric = useGenericResponse;
   276→		var dataTypes = responses.stream().map(r -> r.dataType).collect(Collectors.toSet());
   277→
   278→		if (!responseGeneric && responses.size() > 1) {
   279→			LOG.info("operation {} has multiple responses {}, use generic response",
   280→					operation.nickname, responsesCodes);
   281→			responseGeneric = true;
   282→		}
   283→
   284→		if (!responseGeneric && responses.stream().anyMatch(r -> r.hasHeaders)) {
   285→			LOG.info("operation {} has response with header, use generic response", operation.nickname);
   286→			responseGeneric = true;
   287→		}
   288→
   289→		if (operation.returnType != null && dataTypes.size() > 1) {
   290→			LOG.info("operation {} has multiple responses {} with multiple models {}, erase return type",
   291→					operation.nickname, responsesCodes, dataTypes);
   292→			operation.returnType = null;
   293→		}
   294→
   295→		if ((operation.returnType != null || !responseGeneric) && produces.size() > 1) {
   296→			var specResponse = (ApiResponse) responses.get(0).vendorExtensions.get(ApiResponse.class.getName());
   297→			var returnTypes = specResponse.getContent().values().stream().collect(Collectors.toSet());
   298→			if (returnTypes.size() > 1) {
   299→				var mediaTypes = produces.stream().flatMap(m -> m.values().stream()).collect(Collectors.toSet());
   300→				LOG.info("operation {} has multiple media types {} with multiple models, erase return type",
   301→						operation.nickname, mediaTypes);
   302→				operation.returnType = null;
   303→				responseGeneric = true;
   304→			}
   305→		}
   306→
   307→		// store method and status for micronaut
   308→
   309→		var extensions = operation.vendorExtensions;
   310→		extensions.put("httpMethod", httpMethod.toUpperCase().charAt(0) + httpMethod.substring(1).toLowerCase());
   311→		extensions.put("generic", responseGeneric);
   312→		if (responses.size() == 1) {
   313→			extensions.put("status", HttpStatus.valueOf(responsesCodes.get(0)).name());
   314→		}
   315→		operation.responses.forEach(r -> extensions.put("has" + r.code, true));
   316→
   317→		// jwt provider for tests
   318→
   319→		var hasSecurityJwt = (boolean) operation.vendorExtensions.getOrDefault("has401", false);
   320→		if (generateApiTests && hasSecurityJwt) {
   321→			addSupportingFile(testFolder, invokerPackage, "JwtProvider");
   322→			addSupportingFile(testFolder, invokerPackage, "JwtBuilder");
   323→		}
   324→
   325→		// async
   326→
   327→		if (supportAsync) {
   328→			var isVoid = operation.returnType == null;
   329→			var isStream = Optional.ofNullable(source.getResponses().get("200"))
   330→					.map(ApiResponse::getContent)
   331→					.filter(content -> content.containsKey(MediaType.APPLICATION_JSON_STREAM))
   332→					.isPresent();
   333→			extensions.put("asyncContainer", typeMapping.get("asyncSingle"));
   334→			extensions.put("asyncStream", isStream);
   335→			if (!responseGeneric) {
   336→				if (isVoid) {
   337→					var asyncCompletable = typeMapping.get("asyncCompletable");
   338→					if ("reactor.core.publisher.Mono".equals(asyncCompletable)) {
   339→						extensions.put("asyncContainer", asyncCompletable + "<" + java.lang.Void.class.getName() + ">");
   340→					} else {
   341→						extensions.put("asyncContainer", asyncCompletable);
   342→					}
   343→				} else if ((boolean) operation.vendorExtensions.getOrDefault("has404", false)) {
   344→					extensions.put("asyncContainer", typeMapping.get("asyncMaybe"));
   345→				}
   346→			}
   347→			if (isStream) {
   348→				extensions.put("asyncContainer", typeMapping.get("asyncFlowable"));
   349→			}
   350→		}
   351→
   352→		// add upper case operationId for path constants
   353→
   354→		operation.vendorExtensions.put("operationIdUpperCase",
   355→				StringUtils.underscore(operation.nickname).toUpperCase());
   356→
   357→		operation.pathParams.stream().filter(p -> p.defaultValue != null).forEach(p -> {
   358→			LOG.warn("operation {} has path param {} with unsupported default value {}, default removed",
   359→					operation.nickname, p.baseName, p.defaultValue);
   360→			p.defaultValue = null;
   361→		});
   362→
   363→		// for handle client/server specific path
   364→
   365→		var clientPath = operation.path;
   366→		var queryParamsWithArray = operation.queryParams.stream().filter(p -> p.isArray).collect(Collectors.toList());
   367→		if (!queryParamsWithArray.isEmpty()) {
   368→			clientPath = operation.path + "?"
   369→					+ queryParamsWithArray.stream().map(p -> "{&" + p.baseName + "*}").collect(Collectors.joining());
   370→		}
   371→		extensions.put("clientPath", clientPath);
   372→
   373→		// for handle client/server specific path
   374→
   375→		var serverPath = operation.path;
   376→		for (var pathParam : operation.pathParams) {
   377→			var name = pathParam.baseName;
   378→			if (pathParam.isBoolean) {
   379→				serverPath = serverPath.replace("{" + name + "}", "{" + name + ":true|false}");
   380→			} else if (pathParam.isInteger || pathParam.isLong) {
   381→				serverPath = serverPath.replace("{" + name + "}", "{" + name + ":\\\\-?[0-9]+}");
   382→			} else if (pathParam.isUuid) {
   383→				serverPath = serverPath.replace("{" + name + "}", "{" + name + ":" + UUID_PATTERN + "}");
   384→			} else if (pathParam.maxLength != null) {
   385→				serverPath = serverPath.replace("{" + name + "}", "{" + name + ":" + pathParam.maxLength + "}");
   386→			} else if (pathParam.pattern != null && !pathParam.pattern.contains("{")) {
   387→				serverPath = serverPath.replace("{" + name + "}", "{" + name + ":" + pathParam.pattern + "}");
   388→			}
   389→		}
   390→		extensions.put("serverPath", serverPath);
   391→
   392→		return operation;
   393→	}
