   407→	@Override
   408→	public Map<String, ModelsMap> updateAllModels(Map<String, ModelsMap> objs) {
   409→		var superObjs = super.updateAllModels(objs);
   410→
   411→		// remove AllOf
   412→
   413→		objs.entrySet().removeIf(e -> e.getKey().endsWith("_allOf"));
   414→
   415→		Map<String, CodegenModel> allModels = getAllModels(objs);
   416→		for (CodegenModel model : allModels.values()) {
   417→
   418→			// check if composed schemas for additional properties should be handled and apply to the map if so.
   419→
   420→			if (supportsAdditionalPropertiesWithComposedSchema && model.getAdditionalProperties() != null) {
   421→				model.getVendorExtensions().put("additionalPropertiesMap", Map.of(
   422→						"keyType", "java.lang.String",
   423→						"valueType", model.getAdditionalProperties().getDataType()));
   424→			}
   425→
   426→			// handle discriminator
   427→
   428→			var discriminator = model.discriminator;
   429→			if (discriminator == null) {
   430→				continue;
   431→			}
   432→
   433→			// remove discriminator type
   434→
   435→			model.vars.stream()
   436→					.filter(property -> property.getName().equals(discriminator.getPropertyName()))
   437→					.findAny().ifPresent(property -> {
   438→						discriminator.setPropertyType(property.getDataType());
   439→						model.vars.remove(property);
   440→					});
   441→
   442→			// add discriminator value to submodel
   443→
   444→			for (var mappedModel : discriminator.getMappedModels()) {
   445→
   446→				var subModel = allModels.get(mappedModel.getModelName());
   447→				if (subModel == null) {
   448→					LOG.warn("{} - model in discriminator {} with name {} not found",
   449→							model.name, discriminator.getPropertyName(), mappedModel.getModelName());
   450→					continue;
   451→				}
   452→				if (subModel.parentModel == null) {
   453→					subModel.parentModel = model;
   454→					subModel.parent = model.getClassname();
   455→					LOG.warn("{} added missing sub model {}", model.name, subModel.name);
   456→				}
   457→				subModel.vars.removeIf(property -> property.getName().equals(discriminator.getPropertyName()));
   458→
   459→				Map<String, Object> extensions = subModel.getVendorExtensions();
   460→				extensions.put("discriminatorPropertyGetter", discriminator.getPropertyGetter());
   461→				extensions.put("discriminatorPropertyType", discriminator.getPropertyType());
   462→				switch (discriminator.getPropertyType()) {
   463→					case "java.lang.String":
   464→						extensions.put("discriminatorPropertyValue", '"' + mappedModel.getMappingName() + '"');
   465→						break;
   466→					case "java.lang.Long":
   467→					case "java.lang.Integer":
   468→					case "java.lang.Double":
   469→					case "java.lang.Float":
   470→						extensions.put("discriminatorPropertyValue", mappedModel.getMappingName());
   471→						break;
   472→					default:
   473→						extensions.put("discriminatorPropertyValue", discriminator.getPropertyType() + "."
   474→								+ toEnumVarName(mappedModel.getMappingName(), ""));
   475→				}
   476→			}
   477→		}
   478→
   479→		return superObjs;
   480→	}
