   560→	@Override
   561→	public String toExampleValue(Schema schema) {
   562→
   563→		// first choice: use the example, provided from the spec
   564→		// second choice: use the default provided by the spec
   565→		// special handling for enum: if no example or default is provided, use the first value
   566→		Optional<String> value = Optional
   567→				.ofNullable(schema.getExample())
   568→				.or(() -> Optional.ofNullable(schema.getDefault()))
   569→				.or(() -> Optional.ofNullable(schema.getEnum()).flatMap(e -> e.stream().findFirst()))
   570→				.map(Object::toString);
   571→
   572→		// third choice: set type-specific default examples
   573→
   574→		if (ModelUtils.isBooleanSchema(schema)) {
   575→			return value.orElse("false");
   576→		}
   577→		if (ModelUtils.isLongSchema(schema)) {
   578→			return value.orElse("100L") + "L";
   579→		}
   580→		if (ModelUtils.isFloatSchema(schema)) {
   581→			return value.orElse("12.34") + "F";
   582→		}
   583→		if (ModelUtils.isDoubleSchema(schema)) {
   584→			return value.orElse("43.21") + "D";
   585→		}
   586→		if (ModelUtils.isIntegerSchema(schema) || ModelUtils.isShortSchema(schema)) {
   587→			return value.orElse("12");
   588→		}
   589→		if (ModelUtils.isNumberSchema(schema)) {
   590→			return value.map(v -> "java.lang.Number.valueOf(\"" + v + "\")").orElse("12.34");
   591→		}
   592→
   593→		if (ModelUtils.isDateSchema(schema)) {
   594→			if (typeMapping.get(schema.getType()).equals("java.time.LocalDate")) {
   595→				return "java.time.LocalDate." + value.map(v -> "parse(\"" + v + "\")").orElse("now()");
   596→			} else {
   597→				// we cannot provide a valid example for all possible date types
   598→				return "null";
   599→			}
   600→		}
   601→		if (ModelUtils.isDateTimeSchema(schema)) {
   602→			if (typeMapping.get(schema.getType()).equals("java.time.Instant")) {
   603→				return "java.time.Instant." + value.map(v -> "parse(\"" + v + "\")").orElse("now()");
   604→			} else {
   605→				// we cannot provide a valid example for all possible date types
   606→				return "null";
   607→			}
   608→		}
   609→		if (ModelUtils.isByteArraySchema(schema) || ModelUtils.isBinarySchema(schema)) {
   610→			return value.orElse("\"byteArray\".getBytes()");
   611→		}
   612→		if (ModelUtils.isFileSchema(schema)) {
   613→			return value.orElse("\"myFile\".getBytes()");
   614→		}
   615→		if (ModelUtils.isUUIDSchema(schema)) {
   616→			return "java.util.UUID." + value.map(v -> "fromString(\"" + v + "\")").orElse("randomUUID()");
   617→		}
   618→		if (ModelUtils.isURISchema(schema)) {
   619→			return "java.net.URI.create(\"" + value.orElse("my:uri") + "\")";
   620→		}
   621→		if (ModelUtils.isEmailSchema(schema)) {
   622→			return '"' + value.orElse("mail@example.org") + '"';
   623→		}
   624→		if (ModelUtils.isStringSchema(schema)) {
   625→			return '"' + value.orElse("string") + '"';
   626→		}
   627→
   628→		if (ModelUtils.isMapSchema(schema)) {
   629→			return "java.util.Map." + value
   630→					.map(v -> (Map<?, ?>) new org.yaml.snakeyaml.Yaml().loadAs(v, Map.class))
   631→					.filter(map -> !map.isEmpty())
   632→					.map(map -> map.entrySet().stream()
   633→							.map(e -> "new java.util.AbstractMap.SimpleEntry(\""
   634→									+ e.getKey() + "\", \"" + e.getValue() + "\")")
   635→							.collect(Collectors.joining(", ")))
   636→					.map(map -> "ofEntries(" + map + ")")
   637→					.orElse("of()");
   638→		}
   639→		if (ModelUtils.isSet(schema)) {
   640→			return "java.util.Set.of(" + value.map(v -> v.substring(1, v.length() - 1)).orElse("") + ")";
   641→		}
   642→		if (ModelUtils.isArraySchema(schema)) {
   643→			return "java.util.List.of(" + value.map(v -> v.substring(1, v.length() - 1)).orElse("") + ")";
   644→		}
   645→
   646→		// if no example can be generated, leave it null.
   647→		return "null";
   648→	}
