   651→
   652→	private void addSupportingFile(String folder, String packageString, String file) {
   653→		var templateFile = "support/" + file + ".mustache";
   654→		var destinationFilename = folder + "/" + packageString.replace(".", "/") + "/" + file + ".java";
   655→		var supportingFile = new SupportingFile(templateFile, destinationFilename);
   656→		if (!supportingFiles.contains(supportingFile)) {
   657→			supportingFiles.add(supportingFile);
   658→		}
   659→	}
   660→}
